fn solve(a: i8, b: i8, c: i8) -> i8 {
    // Promote to i16 to avoid overflow when summing up to 300
    let (a16, b16, c16) = (a as i16, b as i16, c as i16);

    // sum of all three sides
    let sum = a16 + b16 + c16;
    // find the largest side
    let max_side = a16.max(b16).max(c16);
    // sum of the two smaller sides
    let sum_other = sum - max_side;

    if sum_other > max_side {
        // already satisfies strict triangle inequality
        0
    } else {
        // need (max_side - sum_other + 1) increments to make sum_other > max_side
        (max_side - sum_other + 1) as i8
    }
}

